import type { HTMLAttributes } from "react";

const join = (base: string, extra = "") => `${base} ${extra}`.trim();
export function TypographyH1({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h1 className={join("co-scroll-m-20 co-text-4xl co-font-bold co-tracking-tight", className)} {...props} />; }
export function TypographyH2({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h2 className={join("co-scroll-m-20 co-border-b co-pb-2 co-text-3xl co-font-semibold", className)} {...props} />; }
export function TypographyH3({ className, ...props }: HTMLAttributes<HTMLHeadingElement>) { return <h3 className={join("co-scroll-m-20 co-text-2xl co-font-semibold", className)} {...props} />; }
export function TypographyP({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={join("co-leading-7 [&:not(:first-child)]:co-mt-6", className)} {...props} />; }
export function TypographyLead({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={join("co-text-xl co-text-black/60", className)} {...props} />; }
export function TypographyMuted({ className, ...props }: HTMLAttributes<HTMLParagraphElement>) { return <p className={join("co-text-sm co-text-black/60", className)} {...props} />; }
